// and ex.suffix(i).suffix(j) = ex.suffix(i+j)
proof fn get_always_witness_from_eventually<T>(
    ex: Execution<T>,
    p: TempPred<T>,
    i: nat,
) -> (j: nat)
    requires eventually(always(p)).satisfied_by(ex.suffix(i)),
    ensures always(p).satisfied_by(ex.suffix(i).suffix(j)),
{
